def burger_counts(tomato_slices, cheese_slices):
 jumbo=(tomato_slices-2*cheese_slices)//2;small=cheese_slices-jumbo
 return [jumbo,small] if jumbo>=0 and small>=0 and 4*jumbo+2*small==tomato_slices else []

